from __future__ import annotations
from .canonical import with_digest
def build_handoff(run:dict,decision:dict,matrix:dict,evidence:dict,risk:dict,events:dict,provenance:dict)->dict:
    body={'schema_version':'1.0.0','handoff_type':'ACL12_TO_ACL13','security_hardening_run_id':run['security_hardening_run_id'],'runtime_custody_run_id':run['runtime_custody_run_id'],'security_readiness_decision':decision['decision'],'security_readiness_decision_digest':decision['readiness_decision_digest'],'security_control_matrix_digest':matrix['assessment_digest'],'security_evidence_bundle_digest':evidence['evidence_bundle_digest'],'security_risk_register_digest':risk['register_digest'],'event_ledger_digest':events['ledger_digest'],'provenance_graph_digest':provenance['graph_digest'],'required_acl13_actions':['VERIFY_SECURITY_READINESS_PACKAGE','BUILD_ONE_HOUR_ASSESSMENT_PRODUCT','ISSUE_NON_CAPITAL_ASSESSMENT_RESULT'],'forbidden_acl13_actions':['INVENT_PRODUCTION_SECURITY_EVIDENCE','AUTHORIZE_RUNTIME_ACTIVATION','AUTHORIZE_LIVE_ORDER','ACTIVATE_CAPITAL','ACCESS_PRODUCTION_KEYS'],'production_security_ready':False,'runtime_generation_allowed':False,'runtime_activation_allowed':False,'live_order_submission_allowed':False,'capital_activation_allowed':False,'production_key_access_allowed':False}
    return with_digest(body,'handoff_digest')
